import java.util.Scanner;
public class Main {
  public static void main(String[] args) {
    Scanner ch = new Scanner(System.in);
    int line2val = ch.nextInt();
    int[] minCost = new int[line2val];
    for(int steps = 0; steps<line2val; steps++) {
      minCost[steps] =ch.nextInt();
    }
    int maxium = bubbleSort(minCost, line2val);
    for(int steps = 0; steps<line2val; steps++) {
      if(steps<line2val-1){
        System.out.print(minCost[steps] + " ");
      }else {
        System.out.println(minCost[steps]);
      }
    }
    System.out.println(maxium);
  }

  public static int bubbleSort(int[] minCost,int line2val) {
    boolean arrayTwoDimension = true;
    int maxium = 0;
    while(arrayTwoDimension == true) {
      arrayTwoDimension = false;
      for(int minj = line2val-1;minj>0; minj--) {
        if(minCost[minj]<minCost[minj-1]) {
          int dist = minCost[minj];
          minCost[minj] = minCost[minj-1];
          minCost[minj-1] = dist;
          maxium++;
          arrayTwoDimension = true;
        }
      }
    }
    return maxium;
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {
	public static void main(String[] args) {
		BufferedReader opeIndex = new BufferedReader(new InputStreamReader(System.in));
		try {
			int n = Integer.parseInt(opeIndex.readLine());
			int[] now_time = new int[n];
			String input = opeIndex.readLine();
			String[] size = input.split("\\s");
			for (int cost = 0; cost < now_time.length; cost++) {
				now_time[cost] = Integer.parseInt(size[cost]);
			}
			System.out.println(DC_op(now_time));
		} catch (IOException cur) {
			cur.printStackTrace();
		}

	}

	// バブルソート
	public static int DC_op(int[] now_time) {
		int numOfQuestion = 0;// 交換回数
		boolean lastTotal = true;
		for (int cost = 0; lastTotal; cost++) { // iは未ソート部分列の先頭インデックス
			lastTotal = false;
			for (int items = now_time.length - 1; items > cost; items--) {
				if (now_time[items] < now_time[items - 1]) {
					int second = now_time[items - 1];
					now_time[items - 1] = now_time[items];
					now_time[items] = second;
					lastTotal = true;
					numOfQuestion++;
				}
			}

		}
		// 表示
		String itemsList = Arrays.toString(now_time);
		System.out.println(itemsList.replace("[", "").replace("]", "").replace(",", ""));
		return numOfQuestion;
	}

}

