public class Main {

	/**
	 *
	 * @param args
	 */
	public static void main(String[] args) {

		Scanner boundDistance = new Scanner(System.in); // 入力
		int ng = Integer.parseInt(boundDistance.nextLine()); // 要素数

		// ソート対象配列の読み込み
		String[] int2Array = boundDistance.nextLine().split(" ");
		int[] intArray = new int[int2Array.length];
		for (int si = 0; si < int2Array.length; si++) {
			intArray[si] = Integer.parseInt(int2Array[si]);
		}

		// 読み込み終了
		boundDistance.close();

		// ソート
		int current = _insetrionSort(ng, intArray);

		// 結果出力
		for (int si = 0; si < intArray.length; si++) {
			if (si < intArray.length - 1) {
				System.out.print(intArray[si] + " ");
			} else {
				System.out.println(intArray[si]);
			}
		}
		System.out.println(current);
		;

	}

	/**
	 * 指定された整数配列を選択ソートする。
	 *
	 * @param n 要素数
	 * @param targetArray 選択ソートしたい整数配列
	 * @return 入れ替え回数
	 */
	private static int _insetrionSort(int ng, int[] intArray) {

		int current = 0; // 入れ替え回数
		for (int si = 0; si < ng; si++) {
			int index = si; // 最小値の要素番号
			for (int heightTargets = si; heightTargets < ng; heightTargets++) {
				// 最小値より低い値があったら
				if (intArray[heightTargets] < intArray[index]) {
					// 最小値の要素番号を更新
					index = heightTargets;
				}
			}
			// 最小値の値と左端を入れ替える
			if (si != index) {
				isPrintableChar(intArray, index, si);
				current++;
			}
		}

		return current;
	}

	/**
	 * 配列内の2つの要素を入れ替える。
	 *
	 * @param array
	 *            入れ替えたい要素を含む配列
	 * @param a
	 *            入れ替えたい要素のindex
	 * @param b
	 *            入れ替えたい要素のindex
	 */
	private static void isPrintableChar(int[] array, int ans, int b) {
		int values = array[ans];
		array[ans] = array[b];
		array[b] = values;
	}

}

