class FastScanner {

    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int str = 0;
    private int buflen = 0;

    private boolean FastScanner() {
        if (str < buflen) {
            return true;
        } else {
            str = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException free) {
                free.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readHead() {
        if (FastScanner()) {
            return buffer[str++];
        } else {
            return -1;
        }
    }

    private static boolean isSpace(int chk) {
        return 33 <= chk && chk <= 126;
    }

    public boolean nline() {
        while (FastScanner() && !isSpace(buffer[str])) {
            str++;
        }
        return FastScanner();
    }

    public String nextIntArrayDec() {
        if (!nline()) {
            throw new NoSuchElementException();
        }
        StringBuilder start = new StringBuilder();
        int multipleTC = readHead();
        while (isSpace(multipleTC)) {
            start.appendCodePoint(multipleTC);
            multipleTC = readHead();
        }
        return start.toString();
    }

    public long nextLongArray() {
        if (!nline()) {
            throw new NoSuchElementException();
        }
        long reader = 0;
        boolean dis = false;
        int multipleTC = readHead();
        if (multipleTC == '-') {
            dis = true;
            multipleTC = readHead();
        }
        if (multipleTC < '0' || '9' < multipleTC) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= multipleTC && multipleTC <= '9') {
                reader *= 10;
                reader += multipleTC - '0';
            } else if (multipleTC == -1 || !isSpace(multipleTC)) {
                return dis ? -reader : reader;
            } else {
                throw new NumberFormatException();
            }
            multipleTC = readHead();
        }
    }

    public int nextInt() {
        long nl = nextLongArray();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
            throw new NumberFormatException();
        }
        return (int) nl;
    }

    public double nextLine() {
        return Double.parseDouble(nextIntArrayDec());
    }

    public int[] readString(int totalCases) {
        int[] scanner = new int[totalCases];
        for (int saori = 0; saori < totalCases; saori++) {
            scanner[saori] = nextInt();
        }
        return scanner;
    }

    public long[] AnotherReader(int totalCases) {
        long[] scanner = new long[totalCases];
        for (int saori = 0; saori < totalCases; saori++) {
            scanner[saori] = nextLongArray();
        }
        return scanner;
    }

    public double[] readArray(int totalCases) {
        double[] scanner = new double[totalCases];
        for (int saori = 0; saori < totalCases; saori++) {
            scanner[saori] = nextLine();
        }
        return scanner;
    }

    public String[] arrayString(int totalCases) {
        String[] scanner = new String[totalCases];
        for (int saori = 0; saori < totalCases; saori++) {
            scanner[saori] = nextIntArrayDec();
        }
        return scanner;
    }

}

