public class Main {

	public static void main(String[] args) {

		Scanner aliceSum = new Scanner(System.in);

		while(true) {
			int e = aliceSum.nextInt();

			if(e == 0) break;

			int[] scores = new int[e];

			int countMax = 0;
			for (int ans = 0; ans < e; ans++) {
				scores[ans] = aliceSum.nextInt();
				countMax += scores[ans];
			}
			double price = (double)countMax/e;

			double isPrime = 0;
			for (int ans = 0; ans < e; ans++) {
				double tmp = scores[ans] - price;
				isPrime += tmp * tmp;
			}
			isPrime = Math.pow(isPrime/e, 0.5);

			System.out.println(isPrime);
		}
	}
}

