	public static int[] checkInt(int[] index){
		int[] before = index;
		int sameNum = 0;
		for(int sum = 0 ; sum < index.length; sum++){
			for(int numberOfCoordinates = sum+1 ; numberOfCoordinates < index.length;numberOfCoordinates++){
				if(before[sum] > before[numberOfCoordinates]){
					sameNum = before[sum];
					before[sum] = before[numberOfCoordinates];
					before[numberOfCoordinates] = sameNum;
				}
			}
		}
		return before;
	}

}

