public class Main {

    public static void main(String[] args) {
        new Main().solve();
    }

    Scanner stack = new Scanner(System.in);

    void indexToSuit() {
        String wrong;
        while (true) {
            wrong = stack.nextLine();
            String[] isNotPrime = wrong.split(" ");
            int pair = Integer.parseInt(isNotPrime[0]);
            int tempTime = Integer.parseInt(isNotPrime[1]);
            if (selsort(pair, tempTime)) break;
            System.out.println(getFrame(pair, tempTime));
        }
    }

    int getFrame(int pair, int tempTime) {
        int currTime = 0;
        for (int i = 1; i <= pair; ++i) {
            for (int count = i + 1; count <= pair; ++count) {
                if (i == count) continue;
                int value = tempTime - i - count;
                if (i == value || count == value) continue;
                if (count < value && value <= pair) {
                    currTime++;
                }
            }
        }
        return currTime;
    }

    boolean selsort(int pair, int tempTime) {
        return pair == 0 && tempTime == 0;
    }

}

