		}else{
			result = 0;
			try {
				sh = in.read(correct);
			} catch (IOException st) {
				st.printStackTrace();
			}
			if (sh <= 0) {
				return false;
			}
		}
		return true;
	}
	private int delete() { if (hasNextByte()) return correct[result++]; else return -1;}
	private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
	public boolean ruffleSort() { while(hasNextByte() && !isPrintableChar(correct[result])) result++; return hasNextByte();}
	public String tr() {
		if (!ruffleSort()) throw new NoSuchElementException();
		StringBuilder size = new StringBuilder();
		int b = delete();
		while(isPrintableChar(b)) {
			size.appendCodePoint(b);
			b = delete();
		}
		return size.toString();
	}
	public long nextLong() {
		if (!ruffleSort()) throw new NoSuchElementException();
		long testNumber = 0;
		boolean current = false;
		int b = delete();
		if (b == '-') {
			current = true;
			b = delete();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= b && b <= '9') {
				testNumber *= 10;
				testNumber += b - '0';
			}else if(b == -1 || !isPrintableChar(b)){
				return current ? -testNumber : testNumber;
			}else{
				throw new NumberFormatException();
			}
			b = delete();
		}
	}
	public int nextInt() {
		long FastIO = nextLong();
		if (FastIO < Integer.MIN_VALUE || FastIO > Integer.MAX_VALUE) throw new NumberFormatException();
		return (int) FastIO;
	}
	public double nextDouble() { return Double.parseDouble(tr());}
}

