public class Main {

	static int solve(String breakPoint, String primeNum) {
		int taroP = 1001;

		for (int tmp = 0; tmp < breakPoint.length() - primeNum.length() + 1; tmp++) {
			int cs = 0;
			for (int price1 = 0; price1 < primeNum.length(); price1++) {
				if (breakPoint.charAt(tmp + price1) != primeNum.charAt(price1))
					cs++;
			}
			if (cs < taroP)
				taroP = cs;
		}

		return taroP;
	}

	public static void main(String[] args) {
		Scanner T_timeLimit = new Scanner(System.in);

		String breakPoint, primeNum;
		breakPoint = T_timeLimit.next();
		primeNum = T_timeLimit.next();
		int taro = solve(breakPoint, primeNum);
		System.out.println(taro);

		T_timeLimit.close();
	}
}

