        InputStream cur = System.in;
        OutputStream outputStream = System.out;
        Scanner in = new Scanner(cur);
        PrintWriter result = new PrintWriter(outputStream);
        B ret = new B();
        ret.solve(1, in, result);
        result.close();
    }

    static class B {
        public void calc_rounding_quo(int testNumber, Scanner in, PrintWriter result) {
            // 入力
            long ah = Long.parseLong(in.next());
            long ai = Long.parseLong(in.next());
            long colors = Long.parseLong(in.next());
            long curans = Long.parseLong(in.next());
            long check = 0;
            long tempI = curans;

            if (ah > 0) {
                if (ah >= curans) check += curans;
                else check += ah;
                tempI -= ah;
                ah = ah - curans;
                curans = tempI;
            }
            if (ah <= 0 && ai > 0 && curans > 0) {
                tempI -= ai;
                ai = ai - curans;
                curans = tempI;
            }
            if (ah <= 0 && ai <= 0 && colors > 0 && curans > 0) {
                check -= curans;
            }

            // 出力
            result.println(check);

        }

    }
}

