        InputStream stream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(stream);
        InputReader.OutputWriter input = new InputReader.OutputWriter(outputStream);

        long nu = in.nextLong();
        long m = in.nextLong();
        if(nu%m == 0) {
            input.println(0);
        }
        else {
            if(nu < m) {
                input.println(Math.min(nu,m-nu));
            }
            else {
                long dist = nu/m;
                input.println(Math.min(nu-dist*m,++dist*m-nu));
            }
        }
        input.flush();
    }
}

