		int counter = absMinimum.nextInt();

		absMinimum.close();

		List<Integer> numberList = new ArrayList<Integer>();

		int numbers = 2;
		for (int minCost = 1; minCost <= minsum; minCost++) {
			numberList.add(numbers);
			numbers += 2;
		}

		int oddNumber = 1;
		for (int minCost = 1; minCost <= counter; minCost++) {
			numberList.add(oddNumber);
			oddNumber += 2;
		}

