import java.io.IOException;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) throws IOException {

		Scanner sum = new Scanner(System.in);
		int scaanner;
		scaanner = sum.nextInt();

		if (scaanner % 2 == 0) {
			System.out.println(scaanner / 2);
		} else {
			System.out.println(scaanner / 2 + 1);
		}

	}

	/**
	 * 余りを求める。
	 * @param a
	 * @param b
	 * @return 余り。余りがマイナスの時はプラスで返す。ｓ
	 */
	public static long tousasum(long a, long at) {
		long scanner = 0;

		scanner = a % at;

		if (scanner < 0) {
			scanner += at;
		}

		return scanner;
	}

	/**
	 * 乗数を求める ※mod対応
	 * @param a 基数
	 * @param n 乗数
	 * @param primeNumMod 法 mod値 使わない場合は「0」
	 * @return
	 */
	public static long lowerbond(long a, long scaanner, long parse) {

		long cd = 1;

		//乗数が0の場合→1
		if (scaanner == 0)
			return 1;

		if (parse == 0) {
			//modを使わないとき

			while (scaanner > 0) {

				if (scaanner % 2 == 0) {
					//累乗が偶数の時

					a *= a;
					scaanner = scaanner / 2;
				} else {
					//累乗が奇数の時
					cd *= a;
					scaanner--;
				}
			}

			return cd;

		} else {
			//modを使うとき

			//初めに桁を落とす
			a = tousasum(a, parse);

			while (scaanner > 0) {

				if (scaanner % 2 == 0) {
					//累乗が偶数の時

					a *= tousasum(a, parse);
					scaanner = scaanner / 2;

				} else {
					//累乗が奇数の時
					cd *= tousasum(a, parse);
					scaanner--;

				}
			}

			return tousasum(cd, parse);

		}

	}

}

