            remainder.println(root);
        }

    }

    static class readInt {
        private InputStream stream;
        private byte[] buffer = new byte[1024];
        private int number;
        private int bufPointer;

        public readInt(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (bufPointer == -1)
                throw new UnknownError();
            if (number >= bufPointer) {
                number = 0;
                try {
                    bufPointer = stream.read(buffer);
                } catch (IOException ret) {
                    throw new UnknownError();
                }
                if (bufPointer <= 0)
                    return -1;
            }
            return buffer[number++];
        }

        public int nextInt() {
            return Integer.parseInt(nextIntArr());
        }

        public long nextLong() {
            return Long.parseLong(nextIntArr());
        }

        public String nextIntArr() {
            int cl = read();
            while (power(cl))
                cl = read();
            StringBuffer parent = new StringBuffer();
            do {
                parent.appendCodePoint(cl);
                cl = read();
            } while (!power(cl));

            return parent.toString();
        }

        private boolean power(int cl) {
            return cl == ' ' || cl == '\n' || cl == '\r' || cl == '\t' || cl == -1;
        }

    }
}

