        List<Integer> counter = new ArrayList<>();
        counter.add(2);

        int nAndQuantum = (count2 - 3) / 2;
        int[] processes = new int[nAndQuantum];
        for (int min = 0; min < nAndQuantum; min++) {
            processes[min] = 1;
        }
        for (int min = 0; min < nAndQuantum; min++) {
            if (processes[min] == 1) {
                int maxCount = min + min + 3;
                // 遅くなるのでコメントアウト
                counter.add(maxCount);
                for (int m = min + maxCount; m < nAndQuantum; m += maxCount) {
                    processes[m] = 0;
                }
            }
        }

        if(count2 == 2) {
