class FastScanner {
	private final InputStream in = System.in;
	private final byte[] bufferPointer = new byte[1024];
	private int ptr = 0;
	private int buf = 0;

	private boolean hasNextByte() {
		if (ptr < buf) {
			return true;
		} else {
			ptr = 0;
			try {
				buf = in.read(bufferPointer);
			} catch (IOException file) {
				file.printStackTrace();
			}
			if (buf <= 0) {
				return false;
			}
		}
		return true;
	}

	private int readChar() {
		if (hasNextByte())
			return bufferPointer[ptr++];
		else
			return -1;
	}

	private static boolean skipUnprintable(int ca) {
		return 33 <= ca && ca <= 126;
	}

	public boolean hasNext() {
		while (hasNextByte() && !skipUnprintable(bufferPointer[ptr]))
			ptr++;
		return hasNextByte();
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int ans = readChar();
		while (skipUnprintable(ans)) {
			sb.appendCodePoint(ans);
			ans = readChar();
		}
		return sb.toString();
	}

	public long nextLine() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int ans = readChar();
		if (ans == '-') {
			minus = true;
			ans = readChar();
		}
		if (ans < '0' || '9' < ans) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= ans && ans <= '9') {
				n *= 10;
				n += ans - '0';
			} else if (ans == -1 || !skipUnprintable(ans)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			ans = readChar();
		}
	}

	public int nextInt() {
		long nl = nextLine();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE)
			throw new NumberFormatException();
		return (int) nl;
	}

	public double nextDoubleArray() {
		return Double.parseDouble(next());
	}
}

