public class Main {

	public static void main(String[] args) {
		Scanner boundDistance = new Scanner(System.in);
		int numList;				// 参加人数
		long temp;						// 初期持ち点
		long[] boundPoint = new long[100000];	// 各参加者の持ち点
		int partition;			// 問題数

		// 入力の受け取り
		numList = boundDistance.nextInt();
		temp = boundDistance.nextLong();
		partition = boundDistance.nextInt();
		temp -= partition;		// 実質的な初期持ち点 ここに正解数を足し、1以上なら勝ち抜けと考える

		// 参加者全員の持ち点を初期化
		for(int si = 0; si < numList; si++) {
			boundPoint[si] = temp;
		}

		// 正解者リストを受け取り、点数計算を行う
		for(int si = 0; si < partition; si++) {
			boundPoint[boundDistance.nextInt() - 1] += 1;
		}

		// 結果を表示する
		for(int si = 0; si < numList; si++) {
			if(boundPoint[si] >= 1) {
				System.out.println("Yes");
			} else {
				System.out.println("No");
			}
		}

