    }

    static class AX {
        public void toString(int headQ, FastReader curbuf, PrintWriter fi) {
            int primes = curbuf.nextInt();
            int l = curbuf.nextInt();
            fi.println(Math.max(primes + l, Math.max(primes * l, primes - l)));
        }

    }

    static class nextDoubleArray {
        private InputStream Arr;
        private byte[] visited = new byte[1024];
        private int string;
        private int close;
        private FastReader.SpaceCharFilter test;

        public nextDoubleArray(InputStream Arr) {
            this.stream = Arr;
        }

        public int Print() {
            if (close == -1) {
                throw new InputMismatchException();
            }
            if (string >= close) {
                string = 0;
                try {
                    close = Arr.read(visited);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (close <= 0) {
                    return -1;
                }
            }
            return visited[string++];
        }

        public int iarr() {
            int match = Print();
            while (print(match)) {
                match = Print();
            }
            int debugDataPath = 1;
            if (match == '-') {
                debugDataPath = -1;
                match = Print();
            }
            int wolves = 0;
            do {
                if (match < '0' || match > '9') {
                    throw new InputMismatchException();
                }
                wolves *= 10;
                wolves += match - '0';
                match = Print();
            } while (!print(match));
            return wolves * debugDataPath;
        }

        public boolean print(int match) {
            if (test != null) {
                return test.isSpaceChar(match);
            }
            return printLine(match);
        }

        public static boolean printLine(int match) {
            return match == ' ' || match == '\n' || match == '\r' || match == '\t' || match == -1;
        }

        public interface SpaceCharFilter {
            public boolean print(int m);

        }

    }
}

