class FastScanner {
	private final InputStream in = System.in;
	private final byte[] strArr = new byte[1024];
	private int retArr = 0;
	private int xindex = 0;

	private boolean int_arr() {
		if (retArr < xindex) {
			return true;
		} else {
			retArr = 0;
			try {
				xindex = in.read(strArr);
			} catch (IOException str) {
				str.printStackTrace();
			}
			if (xindex <= 0) {
				return false;
			}
		}
		return true;
	}

	private int isSpace() {
		if (int_arr())
			return strArr[retArr++];
		else
			return -1;
	}

	private static boolean longsort(int vis) {
		return 33 <= vis && vis <= 126;
	}

	public boolean solve() {
		while (int_arr() && !longsort(strArr[retArr]))
			retArr++;
		return int_arr();
	}

	public String AnotherReader() {
		if (!solve())
			throw new NoSuchElementException();
		StringBuilder result = new StringBuilder();
		int clk = isSpace();
		while (longsort(clk)) {
			result.appendCodePoint(clk);
			clk = isSpace();
		}
		return result.toString();
	}

	public long nc() {
		if (!solve())
			throw new NoSuchElementException();
		long bufPointer = 0;
		boolean parent = false;
		int clk = isSpace();
		if (clk == '-') {
			parent = true;
			clk = isSpace();
		}
		if (clk < '0' || '9' < clk) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= clk && clk <= '9') {
				bufPointer *= 10;
				bufPointer += clk - '0';
			} else if (clk == -1 || !longsort(clk)) {
				return parent ? -bufPointer : bufPointer;
			} else {
				throw new NumberFormatException();
			}
			clk = isSpace();
		}
	}

	public int nn() {
		long yindex = nc();
		if (yindex < Integer.MIN_VALUE || yindex > Integer.MAX_VALUE)
			throw new NumberFormatException();
		return (int) yindex;
	}

	public double InputStreamScanner() {
		return Double.parseDouble(AnotherReader());
	}
}

