public class Main {
    public static void main(String[] args) {
        Scanner con = new Scanner(System.in);
        int num = con.nextInt();
        int [] len = new int [num];
        for(int med=0;med<num;med++){
            len[med] = con.nextInt();
        }
        int cache = 0;
        int [] max2 = new int [3];
        for(int med=1;med<num-1;med++){
            max2[0]= len[med-1];
            max2[1]= len[med];
            max2[2]= len[med+1];
            binarySearch(max2,0,2);
            if(max2[1]==len[med]){
                cache++;
            }
        }
        System.out.println(cache);
    }
    static void binarySearch(int[] total, int stoneCount, int minr) {
        if (stoneCount >= minr) {
            return;
        }
        int len = total[(stoneCount + minr) / 2];
        int second = stoneCount, resultInput = minr, min;
        while (second <= resultInput) {
            while (total[second] < len) {
                second++;
            }
            while (total[resultInput] > len) {
                resultInput--;
            }
            if (second <= resultInput) {
                min = total[second];
                total[second] = total[resultInput];
                total[resultInput] = min;
                second++;
                resultInput--;
            }
        }
        binarySearch(total, stoneCount, resultInput);
        binarySearch(total, second, minr);
    }
}

