            }

            set.println(column);
        }
    }
}

import java.util.Scanner;

public class Main {
  private static final int value = 1_000_000_007;
  private static void solved(int nk, int maxium, int[] ac) {
    int minIndex = 0;
    int[] score = new int[nk + 1];
    score[0] = 1;
    if (minIndex < maxium && ac[minIndex] == 1) {
      minIndex++;
    } else {
      score[1] = 1;
    }
    for (int minCost = 2; minCost <= nk; minCost++) {
      if (minIndex < maxium && ac[minIndex] == minCost) {
        score[minCost] = 0;
        minIndex++;
      } else {
        score[minCost] = score[minCost - 1] + score[minCost - 2];
        if (score[minCost] >= value) score[minCost] -= value;
      }
    }
    System.out.println(score[nk]);
  }
  public static void main(String[] args) {
    Scanner scan = new Scanner(System.in);
    String[] num = scan.nextLine().split(" ");
    int nk = Integer.parseInt(num[0]);
    int maxium = Integer.parseInt(num[1]);
    int[] ac = new int[maxium];
    for (int minCost = 0; minCost < maxium; minCost++) ac[minCost] = Integer.parseInt(scan.nextLine());
    scan.close();
    solved(nk, maxium, ac);
  }
}

