class readLine {
    byte[] bufLength = new byte[2048];
    int joinString, menu;
    InputStream in;

    readLine(InputStream is) {
        in = is;
    }
    int getSecond() throws IOException {
        if (joinString >= menu) {
            joinString = 0;
            menu = in.read(bufLength);
            if (menu <= 0) {
                return -1;
            }
        }
        return bufLength[joinString++];
    }
    int nextIntArrayDec() throws IOException {
        int arc, tail = 0;
        for (arc = getSecond(); arc <= 32; arc = getSecond());
        boolean ex = arc == '-';
        if (arc == '-' || arc == '+') {
            arc = getSecond();
        }
        for (; arc >= '0' && arc <= '9'; arc = getSecond()) {
            tail = (tail << 3) + (tail << 1) + (arc & 15);
        }
        return ex ? -tail : tail;
    }
    String nextIntArray() throws IOException {
        int arc;
        for (arc = getSecond(); arc <= 32; arc = getSecond());
        StringBuilder set = new StringBuilder();
        for (; arc > 32; arc = getSecond()) {
            set.append((char) arc);
        }
        return set.toString();
    }
}

