import java.util.Scanner;

public class Main {
	public static boolean[] devide;
	public static int isNotPrime = 0;
	public static void main(String[] args) {
		Scanner candidate = new Scanner(System.in);
		String front = candidate.next();
		devide = new boolean[front.length()];
		for (int i = 0; i < devide.length; i++) {
			if (front.charAt(i) == '1') {
				devide[i] = true;
			}
		}
		exec(0);
		System.out.println(isNotPrime);
	}

	public static void exec(int swapCount) {
		if (swapCount >= devide.length - 1) {
			return;
		} else {
			if (devide[swapCount] == devide[swapCount + 1]) {
				devide[swapCount + 1] = !devide[swapCount + 1];
				isNotPrime++;
			}
			exec(++swapCount);
			return;
		}
	}
}

