			if(maxCount > temperature[i]) {
				maxCount = temperature[i];
				med = i;
			}
		}
		cost += maxCount - isNotPrime;
		if(maxCount <= isNotPrime)maxCount = isNotPrime;
		if(maxCount - isNotPrime == 0) isNotPrime = 0;
		getTime(temperature, ans, med - 1, maxCount);
		getTime(temperature, med + 1, streakAry, maxCount);
	}
