class Solver {

    private boolean checkPalindrome(char[] isNotPrime, char[] kari, int s, int stu) {
        int values = isNotPrime.length;
        for (int i = 0; i < values; i++) {
            if (isNotPrime[(s + i) % values] !=  kari[(stu + i) % values]) {
                return false;
            }
        }
        return true;
    }

    public void delete() {
