    Scanner number = new Scanner(System.in);
    char[] status = number.next().toCharArray();
    char[] list = number.next().toCharArray();
    if (isPrime(status, list)) {
      System.out.println("Yes");
    } else {
      System.out.println("No");
    }
  }

  private static boolean isPrime(char[] status, char[] list) {
    for (int i = 0; i < status.length; i++) {
      boolean al = true;
      for (int word = 0; word < status.length; word++) {
        if (status[word] != list[(word + i) % list.length]) {
          al = false;
          break;
        }
      }
      if (al) return true;
    }
    return false;
  }
}

