import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner scan = new Scanner(System.in);
        long nam = scan.nextLong();

        long a2 = 1;
        for(long minCost = 2; minCost * minCost <= nam; minCost++) {
            if(nam % minCost != 0) continue;

            if(Math.abs(minCost - nam/minCost) < Math.abs(a2 - nam/a2))
                a2 = minCost;
        }
		System.out.println(Math.max(isPrime(nam/a2), isPrime(a2)));
    }

    private static int isPrime(long digits) {
        int base = 0;
        while(digits > 0) {
            base++;
            digits /= 10;
        }
        return base;
    }
}

